def parse_pairs(lines):
    result = {}
    for line in lines:
        stripped = line.strip()
        if not stripped:
            continue
        if '=' not in stripped:
            raise ValueError(f"Missing '=' in line: {line!r}")
        key, value = stripped.split('=', 1)
        key = key.strip()
        value = value.strip()
        if not key:
            raise ValueError(f"Empty key in line: {line!r}")
        result[key] = value
    return result

